query:
fragment pr on PullRequest{number}
    query PullRequestSearch(
      $q: String!,
      $type: SearchType!,
      $limit: Int!,
      $endCursor: String,
    ) {
      search(query: $q, type: $type, first: $limit, after: $endCursor) {
        issueCount
        nodes {
          ...pr
        }
        pageInfo {
          hasNextPage
          endCursor
        }
      }
    }
